package analyzer

import (
	"fmt"
	"slices"
	"strings"
	"unicode"
	"unicode/utf8"

	"github.com/go-ego/gse"
)

// embeddedChineseDict 是内嵌的简体中文词典标识。
//
// 用 "zh_s" 而不是 "zh"：实测 "zh"（简+繁）加载要 1.475 秒、约 170 MB 堆，
// 而 "zh_s" 只要 732 毫秒、约 108 MB。繁体场景不在当前目标内，
// 没必要为此付出双倍的内存基线。
const embeddedChineseDict = "zh_s"

// customWordFreq 是追加词条的默认词频。
//
// gse 用词频计算最短路径上的代价，词频越高越倾向于被当作一个整词。
// 取一个偏大的值，让调用方显式加进来的词优先成词。
const customWordFreq = 1e6

// ChineseOptions 配置中文分析器；零值即为一套合理默认。
type ChineseOptions struct {
	// Standard 复用英文侧的规则（最小词长、停用词、全角折叠、词内撇号）。
	Standard StandardOptions

	// Dict 是追加的自定义词典内容：按空白或换行分隔，'#' 起注释。
	//
	// 每行可以写「词 词频 词性」，只取第一列——这样 gse 格式的词典文件
	// 内容也能直接贴进来。
	Dict string

	// DictPath 是追加的自定义词典文件路径；为空表示不加载。
	DictPath string

	// NoSubWords 关闭子词扩展。
	//
	// 默认开启：长词的子词也会进索引，「大学」能命中「大学生」。
	// 关闭后索引更小、写入更快，但只能整词匹配。
	NoSubWords bool
}

// ChineseAnalyzer 是中英文混合分析器。
//
// 分流规则：
//   - 连续汉字交给 gse 做词典分词；
//   - 其余部分（拉丁字母、数字、假名、标点）整块交给 StandardAnalyzer。
//
// 这样英文侧已有的行为——小写化、词内撇号、全角折叠、停用词过滤——
// 全部原样保留，只有中文部分换了算法。
//
// 加载词典约需 0.7 秒与 100 MB 上下的堆，因此**应当只构造一次并复用**。
// 构造完成后状态只读，Analyze 可并发调用（gse 的 Segment/CutSearch
// 经 -race 验证为并发安全）。
type ChineseAnalyzer struct {
	std        *StandardAnalyzer
	seg        gse.Segmenter
	noSubWords bool
}

var _ Analyzer = (*ChineseAnalyzer)(nil)

// NewChinese 创建中文分析器。
//
// 内嵌词典与自定义词条都在这里一次性加载完毕：gse 的词典在并发读取期间
// 不能被修改，所有 AddToken 必须发生在任何 Analyze 之前。
func NewChinese(opts ChineseOptions) (*ChineseAnalyzer, error) {
	seg, err := gse.NewEmbed(embeddedChineseDict)
	if err != nil {
		return nil, fmt.Errorf("analyzer: 加载内嵌中文词典失败: %w", err)
	}

	// 加载词典会打日志，交给调用方的日志系统更合适。
	seg.SkipLog = true

	custom := splitDictWords(opts.Dict)
	for _, w := range custom {
		if err := seg.AddToken(w, customWordFreq); err != nil {
			return nil, fmt.Errorf("analyzer: 追加词条 %q 失败: %w", w, err)
		}
	}

	switch {
	case opts.DictPath != "":
		// LoadDict 结尾自己会做一次 CalcToken，顺带把上面加的内联词条
		// 一起算进去，因此不需要再补。
		if err := seg.LoadDict(opts.DictPath); err != nil {
			return nil, fmt.Errorf("analyzer: 加载词典文件 %q 失败: %w", opts.DictPath, err)
		}

	case len(custom) > 0:
		// 关键一步：AddToken 只往 trie 里写，**不会**更新最短路径所需的
		// 词频统计与子词缓存，少了 CalcToken 新词根本不会被选中。
		//
		// CalcToken 是 O(词典规模)，还会重算全部词条的子词缓存，
		// 因此只能在所有词条加完之后调用一次，绝不能放进循环里。
		seg.CalcToken()
	}

	return &ChineseAnalyzer{
		std:        NewStandardWith(opts.Standard),
		seg:        seg,
		noSubWords: opts.NoSubWords,
	}, nil
}

// Analyze 实现 Analyzer。
func (a *ChineseAnalyzer) Analyze(text string) []Token {
	if text == "" {
		return nil
	}

	tokens := make([]Token, 0, estimateTokens(len(text)))
	var pos uint32

	for i := 0; i < len(text); {
		r, _ := utf8.DecodeRuneInString(text[i:])

		if isHan(r) {
			start := i
			for i < len(text) {
				r2, size2 := utf8.DecodeRuneInString(text[i:])
				if !isHan(r2) {
					break
				}
				i += size2
			}
			tokens, pos = a.analyzeHan(text[start:i], start, tokens, pos)
			continue
		}

		// 非汉字段整块交给英文规则。两个分支各自至少前进一个 rune，
		// 因此循环不会退化。
		start := i
		for i < len(text) {
			r2, size2 := utf8.DecodeRuneInString(text[i:])
			if isHan(r2) {
				break
			}
			i += size2
		}
		tokens, pos = a.std.analyzeInto(text[start:i], start, tokens, pos)
	}

	return tokens
}

// analyzeHan 对一段连续汉字分词，把结果追加到 tokens。
//
// 位置语义与英文侧一致：**每个词占一个位置，被过滤掉的词同样占位**，
// 这样中英混排时位置序列不会错乱。
func (a *ChineseAnalyzer) analyzeHan(text string, base int, tokens []Token, pos uint32) ([]Token, uint32) {
	// gse 的 Segment/CutSearch 只接受 []byte，这里转换一次；
	// 段内后续取词都在这块字节上做，不再重复转换。
	raw := []byte(text)
	words := a.seg.Segment(raw)

	for i := range words {
		w := &words[i]

		word := string(raw[w.Start():w.End()])
		term := strings.ToLower(word)

		if a.std.keep(term, utf8.RuneCountInString(term)) {
			tokens = append(tokens, Token{
				Term:     term,
				Position: pos,
				Start:    base + w.Start(),
				End:      base + w.End(),
			})

			if !a.noSubWords {
				tokens = a.appendSubWords(tokens, word, base+w.Start(), term, pos)
			}
		}
		pos++
	}

	return tokens, pos
}

// appendSubWords 为长词追加子词。
//
// 子词与父词**共享同一个位置**，这是 Lucene SynonymGraphFilter 的语义：
// 短语查询在词级与子词级都能正确对齐，而不会因为插入子词把后续位置整体推后。
//
// 代价是当查询把一个子词和后面的词拼成短语时，可能命中原文中并不相邻的
// 组合（例如「中华万岁」会命中「中华人民共和国万岁」）。
// 这是换取「大学」能命中「大学生」所付出的代价，属已知取舍。
func (a *ChineseAnalyzer) appendSubWords(tokens []Token, word string, base int, parent string, pos uint32) []Token {
	// jieba 的 cut_for_search 只对长度大于 2 的词做扩展，短词没有子词。
	if utf8.RuneCountInString(word) < 3 {
		return tokens
	}

	var seen []string

	for _, sub := range a.seg.CutSearch(word, true) {
		if sub == parent || slices.Contains(seen, sub) {
			continue
		}
		seen = append(seen, sub)

		term := strings.ToLower(sub)
		if !a.std.keep(term, utf8.RuneCountInString(term)) {
			continue
		}

		// 子词必然是本词的一段。找不到就跳过——宁可不加，
		// 也不能给出错误的原文区间，否则高亮会指到别的地方。
		//
		// 用最早出现的匹配：中文词很短，重复字导致的歧义影响有限，
		// 且结果确定可复现。
		idx := strings.Index(word, sub)
		if idx < 0 {
			continue
		}

		tokens = append(tokens, Token{
			Term:     term,
			Position: pos,
			Start:    base + idx,
			End:      base + idx + len(sub),
		})
	}

	return tokens
}

// isHan 报告 r 是否是汉字。
//
// 只把汉字交给 gse：假名、谚文等仍走英文侧的逐字规则，
// 因为当前加载的是中文词典，对它们没有帮助。
func isHan(r rune) bool {
	return unicode.Is(unicode.Han, r)
}

// splitDictWords 把自定义词典文本拆成词条。
//
// 支持 '#' 行注释与 gse 词典的「词 词频 词性」格式（只取第一列）。
func splitDictWords(raw string) []string {
	if raw == "" {
		return nil
	}

	var out []string
	for _, line := range strings.Split(raw, "\n") {
		if i := strings.IndexByte(line, '#'); i >= 0 {
			line = line[:i]
		}
		if fields := strings.Fields(line); len(fields) > 0 {
			out = append(out, fields[0])
		}
	}
	return out
}

internal/index/types.go.content:
package index

import (
	"errors"
	"slices"
)

// DocID 是索引内部使用的稠密文档编号，从 1 开始递增。
//
// 用内部稠密 ID 而不是外部字符串 ID 作为 posting 的主键，
// 是因为求交/求并需要频繁比较与排序：uint32 的归并远快于字符串比较，
// 且 posting 体积可以保持不变（外部 ID 只在文档表里存一份）。
//
// 0 保留为「无效」，便于零值判断。
type DocID uint32

// InvalidDocID 是 DocID 的零值，表示无效文档。
const InvalidDocID DocID = 0

// Document 是索引中保存的文档。
type Document struct {
	// ID 是索引内部编号，对外没有意义，因此不参与 JSON 序列化。
	ID DocID `json:"-"`

	// External 是调用方传入的业务 ID，也是对外唯一的文档标识。
	External string `json:"id"`

	// Fields 是原始字段内容，删除时靠它重新分析以定位 posting。
	Fields map[string]string `json:"fields"`

	// FieldLen 记录每个字段的 token 数，BM25 的长度归一化要用。
	FieldLen map[string]int `json:"-"`

	// TotalLen 是所有字段 token 数之和。
	TotalLen int `json:"-"`
}

// Clone 返回文档的深拷贝。
//
// 索引对外一律返回副本：否则调用方可以在索引锁之外修改内部状态，
// 产生难以复现的数据竞争与脏数据。
func (d *Document) Clone() *Document {
	if d == nil {
		return nil
	}

	c := *d
	c.Fields = make(map[string]string, len(d.Fields))
	for k, v := range d.Fields {
		c.Fields[k] = v
	}
	c.FieldLen = make(map[string]int, len(d.FieldLen))
	for k, v := range d.FieldLen {
		c.FieldLen[k] = v
	}
	return &c
}

// Posting 是「某个词条在某篇文档中出现」的记录。
type Posting struct {
	DocID DocID `json:"doc_id"`

	// TF 是该词条在这篇文档这个字段里的出现次数。
	TF uint32 `json:"tf"`

	// Positions 是各次出现的位置，严格递增，短语查询靠它判定相邻。
	Positions []uint32 `json:"positions"`
}

// PostingList 是某个 (字段, 词条) 的全部出现记录。
//
// Postings 按 DocID 严格升序：DocID 单调递增且删除会整条摘除，
// 因此插入时直接 append 即可维持有序，求交/求并得以走双指针归并。
type PostingList struct {
	Postings []Posting `json:"postings"`
	DF       uint32    `json:"df"`
}

// indexOf 在有序 posting 列表中二分查找指定 DocID。
func (pl *PostingList) indexOf(id DocID) (int, bool) {
	return slices.BinarySearchFunc(pl.Postings, id, func(p Posting, target DocID) int {
		switch {
		case p.DocID < target:
			return -1
		case p.DocID > target:
			return 1
		default:
			return 0
		}
	})
}

// Stats 描述索引的当前规模。
type Stats struct {
	// Docs 是未删除的文档数。
	Docs int `json:"docs"`
	// Terms 是去重后的 (字段, 词条) 组合数。
	Terms int `json:"terms"`
	// Fields 是出现过的字段名数量。
	Fields int `json:"fields"`
	// TotalTokens 是所有文档所有字段的 token 总数。
	TotalTokens uint64 `json:"total_tokens"`
	// AvgDocLen 是平均文档长度（token 数）。
	AvgDocLen float64 `json:"avg_doc_len"`
	// IndexBytes 是索引常驻内存的粗略估算，见 estimateBytesLocked。
	IndexBytes int64 `json:"index_bytes"`
}

// FieldStats 是单个字段的统计量，BM25 的 IDF 与长度归一化都要用。
//
// 注意 IDF 必须按字段计算：同一个词在 title 与 body 中的稀有程度
// 完全不同，混在一起算会让短字段的高信息量被长字段稀释。
type FieldStats struct {
	Field       string  `json:"field"`
	Docs        int     `json:"docs"`
	TotalTokens uint64  `json:"total_tokens"`
	AvgLength   float64 `json:"avg_length"`
}

// 索引返回的哨兵错误，调用方用 errors.Is 判断。
var (
	ErrEmptyExternalID  = errors.New("index: 文档外部 ID 不能为空")
	ErrEmptyFieldName   = errors.New("index: 字段名不能为空")
	ErrDocumentExists   = errors.New("index: 文档已存在")
	ErrDocumentNotFound = errors.New("index: 文档不存在")
	ErrNoFields         = errors.New("index: 文档至少需要一个字段")
	ErrTooManyFields    = errors.New("index: 字段数超出上限")
	ErrDocumentTooLarge = errors.New("index: 文档 token 数超出上限")

	// ErrFieldKindConflict 表示同一字段被赋予了两种类型。
	//
	// 这是**必须报错**的情况而不是可以宽容处理的情况：
	// 一个字段既是数字又是文本时，索引与查询都不知道该按哪套走，
	// 静默选一个只会把问题推迟到更难追查的地方。
	ErrFieldKindConflict = errors.New("index: 字段类型冲突")

	// ErrInvalidFieldKind 表示类型名无法识别。
	ErrInvalidFieldKind = errors.New("index: 非法的字段类型")

	// ErrNotNumericField 表示对非数值字段做了数值/范围操作。
	ErrNotNumericField = errors.New("index: 字段不是数值或时间类型")

	// ErrInvalidFieldValue 表示字段值无法按声明类型解析。
	ErrInvalidFieldValue = errors.New("index: 字段值无法按声明类型解析")
)

