}

// Score 计算「单字段、单词条」对一个文档的 BM25 贡献。
//
// 调用方先用 IDF 求出 idf，再对每个命中文档调用本方法。
// 总分是各字段、各词条贡献之和——注意 IDF 必须按字段分别算。
func (bm BM25) Score(idf float64, tf uint32, docLen, avgDocLen float64) float64 {
